/* Shared factual panels for both the workbench result and the substance bank. */
function cxFacts(item,type){const bank=type==='molecule'?(typeof moleculeFactsExtra==='undefined'?{}:moleculeFactsExtra):(typeof saltFactsExtra==='undefined'?{}:saltFactsExtra);return bank[item.id]||{}}
function cxPhotoKey(item,type){return (type==='molecule'?'cid:':'salt:')+(type==='molecule'?(item.cid||item.id):item.id)}
function cxFormulaCounts(formula){const tokens=formula.match(/[A-Z][a-z]?|\d+|[()]/g)||[];let pos=0;function read(){const out={};while(pos<tokens.length&&tokens[pos]!==')'){let part={};const token=tokens[pos++];if(token==='('){part=read();pos++}else if(/^[A-Z]/.test(token))part[token]=1;else return{};const multiplier=/^\d+$/.test(tokens[pos]||'')?+tokens[pos++]:1;for(const [symbol,n]of Object.entries(part))out[symbol]=(out[symbol]||0)+n*multiplier;}return out}return read()}
function cxComposition(item,type){return type==='molecule'&&!item.referenceOnly?chemCounts(item.atoms):cxFormulaCounts(item.formula)}
function cxFactPanel(item,type){const f=cxFacts(item,type),counts=cxComposition(item,type),bySymbol=new Map(elements.map(e=>[e.symbol,e])),parts=Object.entries(counts);const mass=parts.reduce((sum,[symbol,n])=>sum+(bySymbol.get(symbol)?.atomic_mass||0)*n,0);return `<div class="compound-facts">${[['Forekomst',f.occurrence],['Bruk og betydning',f.uses],['Utseende og form',f.appearance],['Verdt å vite',f.explanation]].filter(([,text])=>text).map(([title,text])=>`<section><h4>${title}</h4><p>${cxEscape(text)}</p></section>`).join('')}<details class="compound-composition"><summary>Hva består ${cxFormula(item.formula)} av?</summary><p>${parts.map(([symbol,n])=>`${n} ${cxEscape(bySymbol.get(symbol)?.name.toLowerCase()||symbol)}atom${n===1?'':'er'}`).join(', ')} ${type==='molecule'?'per molekyl':'per formelenhet'}.</p><p>Beregnet molmasse: ca. ${mass.toLocaleString('nb-NO',{maximumFractionDigits:2})} g/mol. ${type==='salt'?'En formelenhet beskriver forholdet i ionegitteret, ikke et eget saltmolekyl.':''}</p></details>${f.sources?.length?`<details class="compound-sources"><summary>Kilder til fakta</summary><ul>${f.sources.map(source=>`<li><a href="${cxEscape(source.url)}" target="_blank" rel="noreferrer">${cxEscape(source.title)} ↗</a></li>`).join('')}</ul></details>`:''}</div>`}
function cxFactSearch(item,type){return Object.values(cxFacts(item,type)).filter(v=>typeof v==='string').join(' ')}
function cxPhotoFigures(value){const photos=Array.isArray(value)?value:value?[value]:[];return photos.map(p=>`<figure class="chem-photo"><p class="photo-kind">${({sample:'Foto av stoffprøve',mineral:'Foto av mineralprøve',hydrate:'Foto av vannholdige krystaller',context:'Foto fra virkeligheten'})[p.kind]||'Fotografi'}</p><img src="${cxEscape(p.path)}" alt="${cxEscape(p.caption)}" loading="lazy" onerror="this.hidden=true;this.nextElementSibling.hidden=false"><p hidden class="note">Bildet kunne ikke lastes. Se originalbildet i kildelenken.</p><figcaption>${cxEscape(p.caption)}<details><summary>Fotograf, kilde og lisens</summary><p>${cxEscape(p.credit)} · <a href="${cxEscape(p.licenseUrl||p.source)}" target="_blank" rel="noreferrer">${cxEscape(p.license)}</a></p><p>${cxEscape(p.changes||'')}</p><a href="${cxEscape(p.source)}" target="_blank" rel="noreferrer">Originalbilde og metadata ↗</a></details></figcaption></figure>`).join('')||'<p class="photo-missing note">Her viser vi en illustrasjon. Et kontrollert fotografi er foreløpig ikke lagt inn.</p>'}
function cxRefreshPhotos(){document.querySelectorAll('[data-compound-photo]').forEach(host=>{host.innerHTML=cxPhotoFigures(chemistryPhotos[host.dataset.compoundPhoto])})}
